// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    address payable player;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
        player = payable(address(0xABCD));
    }

    function testFuzz_property(uint16 lockOffset) public {
        lockOffset = uint16(bound(lockOffset, 0, 10));

        vm.deal(player, 1 ether);
        vm.prank(player);
        bytes32 fakeHash = keccak256(abi.encodePacked("guess"));
        c.lockInGuess{value: 1 ether}(fakeHash);

        uint256 current = block.number;
        uint256 target = current + uint256(lockOffset);
        vm.roll(target);

        bool ok;
        vm.prank(player);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        if (lockOffset == 1) {
            assertTrue(!ok);
        } else {
            assertTrue(address(c).balance >= 0);
        }
    }
}
